from z3 import *

s = Solver()
colors = [Int(f'c_{i}') for i in range(1, 39)]
for c in colors:
    s.add(c >= 0, c <= 2)

for a in range(1, 39):
    for d in range(1, 39):
        if a + 2*d <= 38:
            s.add(Not(And(colors[a-1] == colors[a+d-1], colors[a-1] == colors[a+2*d-1])))

print(s.check())

